<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Bouncing Ball Physics Playground</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      user-select: none;
    }
    body {
      background-color: #0b0f19;
      color: #f1f5f9;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 20px;
      overflow-x: hidden;
    }
    header {
      margin-bottom: 20px;
      text-align: center;
    }
    h1 {
      font-size: 2.25rem;
      font-weight: 800;
      letter-spacing: -0.025em;
      background: linear-gradient(135deg, #60a5fa, #a855f7, #ec4899);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      margin-bottom: 6px;
    }
    p.subtitle {
      color: #94a3b8;
      font-size: 0.95rem;
    }
    .playground {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 20px;
      width: 100%;
      max-width: 540px;
    }
    .canvas-wrapper {
      position: relative;
      border-radius: 16px;
      padding: 3px;
      background: linear-gradient(135deg, #334155, #1e293b, #475569);
      box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.6), 0 0 30px rgba(99, 102, 241, 0.15);
    }
    #sim {
      width: 500px;
      height: 500px;
      max-width: 100%;
      background: #0f172a;
      border-radius: 13px;
      display: block;
      cursor: crosshair;
      touch-action: none;
    }
    .controls {
      display: flex;
      gap: 12px;
      width: 100%;
      justify-content: center;
      align-items: center;
      flex-wrap: wrap;
    }
    .btn {
      background: #1e293b;
      color: #f8fafc;
      border: 1px solid #334155;
      padding: 10px 22px;
      font-size: 0.95rem;
      font-weight: 600;
      border-radius: 10px;
      cursor: pointer;
      transition: all 0.15s ease;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3);
    }
    .btn:hover {
      background: #334155;
      border-color: #475569;
      transform: translateY(-2px);
      box-shadow: 0 6px 12px -2px rgba(0, 0, 0, 0.4);
    }
    .btn:active {
      transform: translateY(0);
      box-shadow: 0 2px 4px -1px rgba(0, 0, 0, 0.3);
    }
    .btn-primary {
      background: linear-gradient(135deg, #2563eb, #1d4ed8);
      border-color: #3b82f6;
    }
    .btn-primary:hover {
      background: linear-gradient(135deg, #3b82f6, #2563eb);
      border-color: #60a5fa;
    }
    .btn-danger {
      background: linear-gradient(135deg, #9f1239, #881337);
      border-color: #be123c;
      color: #fecdd3;
    }
    .btn-danger:hover {
      background: linear-gradient(135deg, #be123c, #9f1239);
      border-color: #f43f5e;
    }
    .stats {
      font-size: 0.85rem;
      color: #64748b;
      font-weight: 500;
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }
  </style>
</head>
<body>

  <header>
    <h1>Physics Playground</h1>
    <p class="subtitle">Click anywhere inside the canvas or use controls below</p>
  </header>

  <div class="playground">
    <div class="canvas-wrapper">
      <canvas id="sim" width="500" height="500"></canvas>
    </div>

    <div class="controls">
      <button id="drop" class="btn btn-primary">⚡ Drop Ball</button>
      <button id="play" class="btn">Pause</button>
      <button id="clear" class="btn btn-danger">Clear All</button>
    </div>

    <div class="stats">
      <span id="ball-count">Balls: 0</span>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('sim');
    const ctx = canvas.getContext('2d');
    const dropBtn = document.getElementById('drop');
    const playBtn = document.getElementById('play');
    const clearBtn = document.getElementById('clear');
    const ballCountEl = document.getElementById('ball-count');

    const CANVAS_WIDTH = 500;
    const CANVAS_HEIGHT = 500;
    const GRAVITY = 0.45;
    const RESTITUTION = 0.82;

    let balls = [];
    let isRunning = true;
    let animFrameId = null;

    const PALETTE = [
      { fill: '#f43f5e', dark: '#9f1239' },
      { fill: '#3b82f6', dark: '#1d4ed8' },
      { fill: '#10b981', dark: '#047857' },
      { fill: '#f59e0b', dark: '#b45309' },
      { fill: '#8b5cf6', dark: '#6d28d9' },
      { fill: '#ec4899', dark: '#be185d' },
      { fill: '#06b6d4', dark: '#0e7490' },
      { fill: '#a855f7', dark: '#7e22ce' }
    ];

    function draw() {
      ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

      // Background Grid
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 1;
      const gridSize = 50;
      ctx.beginPath();
      for (let x = gridSize; x < CANVAS_WIDTH; x += gridSize) {
        ctx.moveTo(x, 0);
        ctx.lineTo(x, CANVAS_HEIGHT);
      }
      for (let y = gridSize; y < CANVAS_HEIGHT; y += gridSize) {
        ctx.moveTo(0, y);
        ctx.lineTo(CANVAS_WIDTH, y);
      }
      ctx.stroke();

      // Render Balls
      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];
        ctx.save();

        ctx.shadowColor = b.color;
        ctx.shadowBlur = 12;

        const grad = ctx.createRadialGradient(
          b.x - b.r * 0.35,
          b.y - b.r * 0.35,
          b.r * 0.1,
          b.x,
          b.y,
          b.r
        );
        grad.addColorStop(0, '#ffffff');
        grad.addColorStop(0.3, b.color);
        grad.addColorStop(1, b.darkColor || b.color);

        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
      }

      if (ballCountEl) {
        ballCountEl.textContent = `Balls: ${balls.length}`;
      }
    }

    function step(dt = 1) {
      const stepDt = (typeof dt === 'number' && !isNaN(dt)) ? dt : 1;

      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];

        // Apply Gravity
        b.vy += GRAVITY * stepDt;

        // Update Position
        b.x += b.vx * stepDt;
        b.y += b.vy * stepDt;

        // Bounce Left / Right
        if (b.x - b.r < 0) {
          b.x = b.r;
          if (b.vx < 0) b.vx = -b.vx * RESTITUTION;
        } else if (b.x + b.r > CANVAS_WIDTH) {
          b.x = CANVAS_WIDTH - b.r;
          if (b.vx > 0) b.vx = -b.vx * RESTITUTION;
        }

        // Bounce Top / Bottom
        if (b.y - b.r < 0) {
          b.y = b.r;
          if (b.vy < 0) b.vy = -b.vy * RESTITUTION;
        } else if (b.y + b.r > CANVAS_HEIGHT) {
          b.y = CANVAS_HEIGHT - b.r;
          if (b.vy > 0) {
            b.vy = -b.vy * RESTITUTION;
            if (Math.abs(b.vy) < 0.1) b.vy = 0;
          }
        }
      }

      draw();
    }

    function addBall(x, y, vx = 0, vy = 0, r) {
      const radius = (r !== undefined && r !== null && !isNaN(r)) ? Number(r) : 16;
      const theme = PALETTE[Math.floor(Math.random() * PALETTE.length)];

      const ball = {
        x: Number(x),
        y: Number(y),
        vx: Number(vx),
        vy: Number(vy),
        r: radius,
        color: theme.fill,
        darkColor: theme.dark
      };

      balls.push(ball);
      draw();
      return ball;
    }

    function clear() {
      balls = [];
      draw();
    }

    function loop() {
      if (isRunning) {
        step(1);
        animFrameId = requestAnimationFrame(loop);
      }
    }

    // Expose Programmatic API on window.sim
    window.sim = {
      w: CANVAS_WIDTH,
      h: CANVAS_HEIGHT,
      balls: () => balls,
      addBall: addBall,
      clear: clear,
      step: step
    };

    // UI Event Listeners
    canvas.addEventListener('click', (e) => {
      const rect = canvas.getBoundingClientRect();
      const scaleX = canvas.width / rect.width;
      const scaleY = canvas.height / rect.height;
      const x = (e.clientX - rect.left) * scaleX;
      const y = (e.clientY - rect.top) * scaleY;

      const vx = (Math.random() - 0.5) * 8;
      const vy = (Math.random() - 0.5) * 6 - 3;
      addBall(x, y, vx, vy);
    });

    dropBtn.addEventListener('click', () => {
      const x = CANVAS_WIDTH / 2 + (Math.random() - 0.5) * 80;
      const y = 40;
      const vx = (Math.random() - 0.5) * 6;
      const vy = Math.random() * 2;
      addBall(x, y, vx, vy);
    });

    playBtn.addEventListener('click', () => {
      isRunning = !isRunning;
      playBtn.textContent = isRunning ? 'Pause' : 'Play';
      if (isRunning) {
        loop();
      } else if (animFrameId) {
        cancelAnimationFrame(animFrameId);
        animFrameId = null;
      }
    });

    clearBtn.addEventListener('click', () => {
      clear();
    });

    // Initial demo balls
    addBall(150, 100, 3, 0, 18);
    addBall(350, 120, -2, 1, 22);
    addBall(250, 80, 1, -2, 16);

    // Start Animation Loop
    loop();
  </script>
</body>
</html>
